function finishDance(cancelled=false){
 if(countdownTimer){
  clearInterval(countdownTimer);
  countdownTimer=null;
 }
 if(danceState===DANCE_STATES.IDLE&&!cancelled)return;
 danceState=cancelled?DANCE_STATES.IDLE:DANCE_STATES.RESULTS;
 dance=false;
 resetInput();
 setActionLabel('dance','♫ Dans et');
 document.getElementById('notes').replaceChildren();
 document.getElementById('phrase-cursor').style.left='0%';
 document.getElementById('confirm-beat').disabled=true;
 document.getElementById('phrase-level').textContent=cancelled?'SEVİYE 1':'TUR BİTTİ';
 document.getElementById('dock-open').classList.remove('running');

 if(soundOn){
  stopSound();
 }

 if(cancelled){
  danceState=DANCE_STATES.IDLE;
  status.textContent='Dans turu durduruldu';
  document.getElementById('timer').textContent='HAZIR';
  resetDockPreview();
  return;
 }

 points+=danceGame.roundScore;
 updateScore();
 let accuracy=(danceGame.stats.perfect+danceGame.stats.great*0.8+danceGame.stats.good*0.5)/danceGame.count;
 let grade=accuracy>0.93?'S':accuracy>0.82?'A':accuracy>0.68?'B':accuracy>0.5?'C':'D';
 let gradeEl=document.getElementById('grade');
 if(gradeEl)gradeEl.textContent=grade;
 let resScoreEl=document.getElementById('resultscore');
 if(resScoreEl)resScoreEl.textContent=danceGame.roundScore+' PUAN · MAX COMBO '+danceGame.maxCombo;

 let pEl=document.getElementById('perfects');if(pEl)pEl.textContent=danceGame.stats.perfect+' Perfect';
 let gEl=document.getElementById('greats');if(gEl)gEl.textContent=danceGame.stats.great+' Great';
 let gdEl=document.getElementById('goods');if(gdEl)gdEl.textContent=danceGame.stats.good+' Good';
 let mEl=document.getElementById('misses');if(mEl)mEl.textContent=danceGame.stats.miss+' Miss';

 document.getElementById('result').hidden=false;
 status.textContent='Tur tamamlandı · Derece '+grade;
}

