window.addEventListener('keydown',e=>{
 if(e.target.matches('input,textarea'))return;
 if(sequence.includes(e.key)||e.key===' ')e.preventDefault();
 if(e.code==='Escape'){e.preventDefault();handleBack();return}
 if(paused||danceState===DANCE_STATES.PAUSED||danceState===DANCE_STATES.RESULTS||!document.getElementById('songselect').hidden)return;

 if(danceState===DANCE_STATES.PLAYING||danceState===DANCE_STATES.COUNTDOWN){
  if(!e.repeat){
   if(e.code==='KeyF')toggleDance();
   if(sequence.includes(e.key))input(e.key);
   if(e.code==='Space'||e.code==='ControlLeft'||e.code==='ControlRight')confirmDance();
  }
  return; // Dans esnasında WASD hareket tuşları filtrelenir
 }

 keyboardKeys[e.key.toLowerCase()]=true;
 if(['w','a','s','d'].includes(e.key.toLowerCase()))updateTouchMovement();
 else keys[e.key.toLowerCase()]=true;
 if(!e.repeat){
  if(e.code==='KeyE')interact();
  if(e.code==='KeyF')toggleDance();
 }
});

window.addEventListener('keyup',e=>{
 keyboardKeys[e.key.toLowerCase()]=false;
 if(['w','a','s','d'].includes(e.key.toLowerCase()))updateTouchMovement();
 else keys[e.key.toLowerCase()]=false;
});

// Keyboard and touch are separate held sources; releasing one cannot clear the other.
function updateTouchMovement(){
 const held=new Set([...movePointers.values()].flat());
 for(const k of ['a','d','w','s'])keys[k]=!!keyboardKeys[k]||held.has(k);
}
function resetInput(){
 const captures=[...movePointers.keys(),orbitPointerId,joystickPointer].filter(id=>id!==null);
 joystickPointer=null;joystick={x:0,y:0,strength:0};
 const knob=document.getElementById('joystick-knob');if(knob)knob.style.transform='translate(-50%,-50%)';
 movePointers.clear();dancePointers.clear();
 for(const k of Object.keys(keyboardKeys))keyboardKeys[k]=false;
 for(const k of Object.keys(keys))keys[k]=false;
 isMouseDown=false;orbitPointerId=null;pointerStart=null;
 goal=null;navPath=[];marker.visible=false;
 document.querySelectorAll('[data-move],#gamecanvas,#joystick').forEach(el=>{
  // Clear state before release, since lostpointercapture can fire synchronously.
  for(const id of captures)if(el.hasPointerCapture(id))el.releasePointerCapture(id);
 });
}
window.addEventListener('blur',resetInput);
window.meydanBackground=()=>{resetInput();pauseDanceTur()};
window.meydanForeground=resetInput;
window.meydanBack=handleBack;
function handleBack(){
 resetInput();
 if(!document.getElementById('dancepause').hidden){quitDanceFromPause();return}
 if(!document.getElementById('songselect').hidden){closeSongSelect();return}
 if(!document.getElementById('result').hidden){closeResultScreen();return}
 if(!document.getElementById('pausemenu').hidden){setPause(false);return}
 if(dockOpen){setDancePanel(false);return}
 if(danceState===DANCE_STATES.PLAYING||danceState===DANCE_STATES.COUNTDOWN){pauseDanceTur();return}
 setPause(true);
}
// Score at contact, never again on compatibility click or pointer release.
function bindPress(button,action){
 button.onpointerdown=e=>{
  if(e.button!==0||dancePointers.has(e.pointerId))return;
  e.preventDefault();dancePointers.add(e.pointerId);action();
 };
 button.onclick=e=>e.preventDefault();
 button.onkeydown=e=>{
  if(e.code==='Space'||e.code==='Enter'){
   e.preventDefault();e.stopPropagation();if(!e.repeat)action();
  }
 };
}
document.querySelectorAll('.key').forEach((b,i)=>bindPress(b,()=>input(sequence[i])));
bindPress(document.getElementById('confirm-beat'),()=>{if(danceState===DANCE_STATES.IDLE)openSongSelect();else confirmDance()});
for(const event of ['pointerup','pointercancel'])window.addEventListener(event,e=>dancePointers.delete(e.pointerId));

const joystickPad=document.getElementById('joystick');
function canWalk(){return !paused&&danceState===DANCE_STATES.IDLE&&document.getElementById('songselect').hidden}
function moveJoystick(e){
 if(e.pointerId!==joystickPointer)return;
 const value=analogVector(e.clientX-joystickCenter.x,e.clientY-joystickCenter.y,joystickCenter.radius);
 joystick=value;
 document.getElementById('joystick-knob').style.transform=`translate(calc(-50% + ${value.thumbX}px),calc(-50% + ${value.thumbY}px))`;
}
joystickPad.onpointerdown=e=>{
 if(joystickPointer!==null||!canWalk()||e.button!==0)return;
 e.preventDefault();
 const r=joystickPad.getBoundingClientRect();joystickCenter={x:r.x+r.width/2,y:r.y+r.height/2,radius:Math.max(20,r.width/2-22)};
 joystickPointer=e.pointerId;joystickPad.setPointerCapture(e.pointerId);moveJoystick(e);
};
joystickPad.onpointermove=moveJoystick;
joystickPad.onpointerup=joystickPad.onpointercancel=joystickPad.onlostpointercapture=e=>{
 if(e.pointerId!==joystickPointer)return;
 joystickPointer=null;joystick={x:0,y:0,strength:0};
 document.getElementById('joystick-knob').style.transform='translate(-50%,-50%)';
};

document.querySelectorAll('[data-move]').forEach(b=>{
 b.onpointerdown=e=>{
  if(paused||danceState===DANCE_STATES.PLAYING||danceState===DANCE_STATES.COUNTDOWN)return;
  e.preventDefault();
  let [x,z]=b.dataset.move.split(',').map(Number);
  movePointers.set(e.pointerId,[...(x<0?['a']:x>0?['d']:[]),...(z<0?['w']:z>0?['s']:[])]);
  updateTouchMovement();
  b.setPointerCapture(e.pointerId);
 };
 b.onpointerup=b.onpointercancel=b.onlostpointercapture=e=>{
  if(movePointers.delete(e.pointerId))updateTouchMovement();
 };
});


const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),-0.1);
let pointerStart;

renderer.domElement.addEventListener('pointerdown',e=>{if(!paused)pointerStart={id:e.pointerId,x:e.clientX,y:e.clientY}});
renderer.domElement.addEventListener('pointerup',e=>{
 if(paused||danceState===DANCE_STATES.PLAYING||danceState===DANCE_STATES.COUNTDOWN)return; // Dans esnasında tıklayarak yürüme engellendi
 if(!player||!pointerStart||e.pointerId!==pointerStart.id||Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>5)return;
 pointer.set(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2);
 raycaster.setFromCamera(pointer,camera);
 let hit=new THREE.Vector3();
 if(raycaster.ray.intersectPlane(groundPlane,hit)&&!blocked(hit.x,hit.z)){
  navPath=findPath(hit);
  if(!navPath.length){notify('Bu noktaya geçiş yok. Başka bir yer seç.');return}
  goal=navPath.shift();
  marker.position.set(hit.x,0.12,hit.z);
  marker.visible=true;
 }
});

let beatTimer,soundOn=false;

function playTick(isDownbeat, audioTime){
 if(!audioCtx)return;
 try{
  let osc=audioCtx.createOscillator();
  let gain=audioCtx.createGain();
  osc.type=isDownbeat?'sine':'triangle';
  let t=audioTime!==undefined?audioTime:audioCtx.currentTime;
  osc.frequency.setValueAtTime(isDownbeat?115:330,t);
  osc.frequency.exponentialRampToValueAtTime(isDownbeat?45:230,t+0.12);
  gain.gain.setValueAtTime(0.07,t);
  gain.gain.exponentialRampToValueAtTime(0.001,t+0.16);
  osc.connect(gain);
  gain.connect(audioCtx.destination);
  osc.start(t);
  osc.stop(t+0.17);
 }catch(e){}
}

function playGroove(beat){
 playTick(beat%4===0);
 const bass=[65.41,65.41,87.31,77.78][Math.floor(beat/8)%4];
 function tone(freq,type,volume,length){
  const osc=audioCtx.createOscillator(),gain=audioCtx.createGain(),t=audioCtx.currentTime;
  osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,t);gain.gain.exponentialRampToValueAtTime(.001,t+length);
  osc.connect(gain);gain.connect(audioCtx.destination);osc.start(t);osc.stop(t+length);
 }
 tone(bass,'triangle',.055,.24);
 if(beat%2===1)tone(180,'square',.018,.07);
 if(beat%4===0)tone(bass*4,'sine',.025,.4);
}

